const screen = { buttons: 3, inputs: 2, navItems: 1 };
const total = screen.buttons + screen.inputs + screen.navItems;
console.log("Interactive elements: " + total);

function luminance(hex) {
  const c = [0, 2, 4].map(i => {
    const v = parseInt(hex.slice(i + 1, i + 3), 16) / 255;
    return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4);
  });
  return 0.2126 * c[0] + 0.7152 * c[1] + 0.0722 * c[2];
}
function contrast(fg, bg) {
  const l1 = luminance(fg), l2 = luminance(bg);
  const [hi, lo] = l1 > l2 ? [l1, l2] : [l2, l1];
  return (hi + 0.05) / (lo + 0.05);
}
const ratio = contrast("#000000", "#FFFFFF");
console.log("Contrast ratio: " + ratio.toFixed(1) + " - " + (ratio >= 4.5 ? "PASS" : "FAIL"));
